/* Lot 91: radial-gradient radii and gradian angles in the reader's normal form (generated by scripts/lot91_bggen.py; expectations from that model). */

#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssbg.h"

static char g_o[WF_CSSBG_VAL];

static const char *run(const char *f, const char *v) {
    int r;
    if (!strcmp(f, "img")) r = wf_cssbg_image(v, g_o, (int)sizeof(g_o));
    else r = wf_cssbg_gradient(v, (int)strlen(v), g_o, (int)sizeof(g_o));
    if (r <= 0) return g_o[0] ? "REFUSED BUT WRITTEN" : "REFUSED";
    if (r != (int)strlen(g_o)) return "BAD LENGTH";
    return g_o;
}

static void test_l91_radial_0(void) {
    TEST_ASSERT_EQUAL_STRING("radial-gradient(closest-corner at left 10px, rgb(5, 41, 134), #6338ee2e, #09e9348d 26%)", run("grad", "RADIAL-GRADIENT(CLOSEST-CORNER 	 At 	 LEFT 	 10PX, rgb(5, 41, 134), #6338ee2e, #09e9348d  26%)"));
    TEST_ASSERT_EQUAL_STRING("radial-gradient(closest-corner at 25% 75%, navy 57%, rgb(218, 227, 177) 51%, #5dfabb27 67%, rgb(29, 219, 121) 81.6%)", run("grad", "rADiAl-GrAdieNt(CLOSEST-CORNER at 25% 75%,	NAvY 	 57%,	rgb(218, 227, 177) 51%,	#5dfabb27  67%,	rgb(29, 219, 121) 	 81.6%)"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "radiAl-gradiEnt(497%  ELLIPSE  at  left  10px, orange 43%, #93510e53 79%)"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "radIal-gRAdienT(515.5px at left right, rgb(153, 188, 66)  7%, #1638cf92 46%, #71b6fb14)"));
    TEST_ASSERT_EQUAL_STRING("radial-gradient(circle farthest-side at top, #8ab9ee, #186)", run("grad", "radiAl-GRADient(ciRclE	FARTHEST-SIDE	at	top, #8Ab9Ee, #186)"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "RadIaL-graDiENt(1794%, rgb(112, 0, 237)  59%, #4d2963b4 47%, #13f86642 93%)"));
}

